        return n
    dp = [0] * (n + 1)
    dp[1] = 1
    dp[2] = 2
    for i in range(3, n + 1):
        dp[i] = dp[i - 1] + dp[i - 2]
    return dp[n]

def solve(adj):
    if not adj or adj == [[]]:
        return adj
    visited = {}
    def dfs(node):
        if node in visited:
            return visited[node]
        visited[node] = list(adj[node - 1])
        for nei in adj[node - 1]:
            dfs(nei)
        return visited[node]
    dfs(1)
    return [visited[i + 1] if (i + 1) in visited else list(adj[i]) for i in range(len(adj))]

def solve(coins, amount):
    dp = [float('inf')] * (amount + 1)
    dp[0] = 0
    for a in range(1, amount + 1):
        for c in coins:
            if a - c >= 0:
                dp[a] = min(dp[a], 1 + dp[a - c])
    return dp[amount] if dp[amount] != float('inf') else -1

def solve(candidates, target):
    res = []
    def backtrack(start, comb, total):
        if total == target:
            res.append(list(comb))
            return
        if total > target:
            return
        for i in range(start, len(candidates)):
            comb.append(candidates[i])
            backtrack(i, comb, total + candidates[i])
            comb.pop()
    backtrack(0, [], 0)
    return res

def solve(height):
    left, right = 0, len(height) - 1
    max_area = 0
    while left < right:
        width = right - left
        h = min(height[left], height[right])
        max_area = max(max_area, width * h)
        if height[left] < height[right]:
            left += 1
        else:
            right -= 1
    return max_area

def solve(n):
