class Trie:
    def __init__(self):
        self.root = {}
    def insert(self, word):
        node = self.root
        for ch in word:
            if ch not in node:
                node[ch] = {}
            node = node[ch]
        node['$'] = True
    def search(self, word):
        node = self.root
        for ch in word:
            if ch not in node:
                return False
            node = node[ch]
        return '$' in node
    def startsWith(self, prefix):
        node = self.root
        for ch in prefix:
            if ch not in node:
                return False
            node = node[ch]
        return True

def solve(operations, args):
    trie = None
    res = []
    for op, arg in zip(operations, args):
        if op == "Trie" or (trie is None and op != "Trie"):
            trie = Trie()
            if op == "Trie":
                res.append(None)
                continue
        if op == "insert":
            trie.insert(arg)
            res.append(None)
        elif op == "search":
            res.append(trie.search(arg))
        elif op == "startsWith":
            res.append(trie.startsWith(arg))
    return res

