def solve(n, edges):
    parent = list(range(n))
    def find(i):
        if parent[i] == i:
            return i
        parent[i] = find(parent[i])
        return parent[i]
    for u, v in edges:
        parent[find(u)] = find(v)
    return len(set(find(i) for i in range(n)))

def solve(grid):
    if not grid:
        return 0
    rows, cols = len(grid), len(grid[0])
    islands = 0
    def dfs(r, c):
        if r < 0 or r >= rows or c < 0 or c >= cols or grid[r][c] != "1":
            return
        grid[r][c] = "0"
        dfs(r + 1, c)
        dfs(r - 1, c)
        dfs(r, c + 1)
        dfs(r, c - 1)
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == "1":
                dfs(r, c)
                islands += 1
    return islands

def solve(heights):
    if not heights:
        return []
    m, n = len(heights), len(heights[0])
    pac = set()
    atl = set()
    def dfs(r, c, visited):
        visited.add((r, c))
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < m and 0 <= nc < n and (nr, nc) not in visited:
                if heights[nr][nc] >= heights[r][c]:
                    dfs(nr, nc, visited)
    for i in range(m):
        dfs(i, 0, pac)
        dfs(i, n - 1, atl)
    for j in range(n):
        dfs(0, j, pac)
        dfs(m - 1, j, atl)
    return sorted([list(p) for p in (pac & atl)])

